static void *kernel_load(const char *name, int flags, char **err, void *ud)
{
    (void)flags; (void)err; (void)ud;
    if (name && (strcmp(name, "xboxkrnl") == 0 || strcmp(name, "xboxkrnl.dll") == 0))
        return (void *)(size_t)0x4B524E4C;
    return 0;
}

static void *kernel_symbol(void *handle, const char *name, char **err, void *ud)
{
    unsigned int i;
    (void)handle; (void)err; (void)ud;
    if (!name) return 0;
    for (i = 0; i < sizeof(kernel_syms) / sizeof(kernel_syms[0]); i++) {
        if (!strcmp(kernel_syms[i].name, name))
            return kernel_syms[i].addr;
    }
    return 0;
}

static void *kernel_close(void *handle, void *ud)
{
    (void)handle; (void)ud;
    return 0;
}

void rxdk_bind_kernel_register(void)
{
    mono_dl_fallback_register(kernel_load, kernel_symbol, kernel_close, 0);
}
